mod tests {
    use super::*;

    fn close(a: f64, b: f64) -> bool {
        (a - b).abs() < 1e-9
    }

    #[test]
    fn a_leaf_holds_a_number_and_no_history() {
        let a = Value::new(2.5);
        assert!(close(a.data(), 2.5));
        assert!(close(a.grad(), 0.0));
        assert!(a.parents().is_empty());
    }

    #[test]
    fn a_clone_is_the_same_node() {
        let a = Value::new(1.0);
        let b = a.clone();
        b.set_grad(4.0);
