        let a = Value::new(2.0);
        let b = Value::new(-3.0);
        let c = Value::new(10.0);
        let f = Value::new(-2.0);
        let d = &(&a * &b) + &c;
        let e = &d * &f;
        e.backward();
        assert!(close(e.data(), -8.0));
        assert!(close(d.grad(), -2.0));
        assert!(close(f.grad(), 4.0));
