        let y = (&(&w * &x) + &b).tanh();
        y.backward();
        let d = 1.0 - y.data() * y.data();
        assert!(close(w.grad(), 2.0 * d));
        assert!(close(x.grad(), 0.5 * d));
        assert!(close(b.grad(), d));
    }

