        let x = Value::new(1.7);
        let w1 = Value::new(0.5);
        let b1 = Value::new(-0.25);
        let w2 = Value::new(-1.5);
        let b2 = Value::new(0.75);

        let stacked = &(&w2 * &(&(&w1 * &x) + &b1)) + &b2;

        let w = &w2 * &w1;
        let b = &(&w2 * &b1) + &b2;
        let single = &(&w * &x) + &b;

