        let loss = mse(&net.forward(&xs), &[1.0]);
        zero_grad(&params);
        loss.backward();
        descend(&params, 0.1);
        let after = mse(&net.forward(&xs), &[1.0]).data();

        assert!(after < before, "loss went from {before} to {after}");
    }

