        c.backward();
        assert!(close(a.grad(), 4.0));

        c.backward();
        assert!(close(a.grad(), 8.0));

        zero_grad(&[a.clone(), b.clone(), c.clone()]);
        c.backward();
        assert!(close(a.grad(), 4.0));
    }
