    type Output = Value;
    fn add(self, rhs: &Value) -> Value {
        Value::from_op(self.data() + rhs.data(), Op::Add, vec![self.clone(), rhs.clone()])
    }
}

impl std::ops::Mul for &Value {
    type Output = Value;
    fn mul(self, rhs: &Value) -> Value {
